from typing import List

def max_fill(grid, capacity):
    import math

    def dfs(x, y, current_capacity, target_capacity):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == 0:
            return 0
        if current_capacity == target_capacity:
            return 1
        if current_capacity > target_capacity:
            return 0

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        res = 0
        for dx, dy in directions:
            x_new, y_new = x + dx, y + dy
            if grid[x_new][y_new] == 0:
                continue
            res += dfs(x_new, y_new, current_capacity + grid[x_new][y_new], target_capacity)
            if res > 10000:
                break
        return res

    max_fill_count = 0
    for row in grid:
        for i in range(len(row)):
            if row[i] == 0:
                continue
            current_capacity = 0
            target_capacity = capacity
            while current_capacity < target_capacity:
                current_capacity += dfs(i, 0, current_capacity, target_capacity)
            max_fill_count = max(max_fill_count, current_capacity)
    return max_fill_count


