def split_words(txt):
    # Check for no spaces in the text
    if ' ' not in txt:
        # Return a list of words split on whitespace
        return txt.split()
    # Check for no commas in the text
    elif ',' not in txt:
        # Return the number of lower-case letters with odd order in the alphabet
        return len([ord(c) - 32 for c in txt if c.islower()])
    else:
        # Return a list of words split on commas
        return txt.split(',')
