def tri(n):
    if n == 1:
        return [3]
    elif n == 2:
        return [1, 3]

    # Initialize the list with the first two elements
    tribonacci = [1, 3]

    # Compute the next elements up to the nth element
    for i in range(2, n):
        if i % 2 == 0:
            tribonacci.append(tribonacci[i-1] + tribonacci[i-2])
        else:
            tribonacci.append(tribonacci[i-1] + tribonacci[i-2] + tribonacci[i])

    return tribonacci
