def is_nested(string):
    def is_nested_helper(subsequence):
        open_brackets = 0
        for char in subsequence:
            if char == '[':
                open_brackets += 1
            elif char == ']':
                open_brackets -= 1
            if open_brackets < 0:
                return False
        return open_brackets == 0

    return is_nested_helper(string)

